package cmd

import (
	"fmt"
	"sort"
	"strings"

	"github.com/alecthomas/kong"
)

func generateBash(parser *kong.Kong) string {
	root := parser.Model.Node
	valueFlags := strings.Join(collectValueFlags(root), "|")
	var b strings.Builder

	b.WriteString(`#!/bin/bash
# bash completion for gccli
# Generated by gccli completion bash

_gccli_completions() {
    # _init_completion is a guard only: bash-completion returns non-zero after
    # it completed a redirection or a $VAR itself. Its words are not used.
    local cur prev words cword
    if type _init_completion &>/dev/null; then
        _init_completion || return
    fi
    # Words come from the line up to the cursor, split at whitespace only, so
    # they are the same with and without bash-completion and on bash 3.2.
    # bash before 4.3 counts COMP_POINT in bytes, and ${s:0:n} counts
    # characters unless the locale is C.
    local line unquoted i w n
    if (( BASH_VERSINFO[0] < 4 || BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 3 )); then
        local LC_ALL=C
    fi
    line=${COMP_LINE:0:COMP_POINT}
    unquoted=${line//[\"\']/}
    IFS=$' \t\n' read -ra words <<< "$unquoted"
    [[ -z $line || $line == *[[:space:]] ]] && words+=("")
    n=$(( ${#words[@]} - 1 ))
    (( n > 0 )) || return

    # bash replaces only its own current word: the text after an open quote,
    # or else the text between the last break character and the cursor.
    # Replies must match that word. bash 3.2 does not split COMP_WORDS at
    # break characters, so take it from the line.
    local c quote=""
    cur=$line
    for ((i = 0; i < ${#line}; i++)); do
        c=${line:i:1}
        case $quote$c in
            \\|\"\\) ((i++)) ;;
            \"|\') quote=$c cur=${line:i+1} ;;
            \"\"|\'\') quote="" cur=$line ;;
        esac
    done
    if [[ -z $quote ]]; then
        for ((i = 0; i < ${#COMP_WORDBREAKS}; i++)); do
            c=${COMP_WORDBREAKS:i:1}
            cur=${cur##*"$c"}
        done
    fi

    # A positional at a command with a default subcommand that takes
    # arguments belongs to that subcommand.
    local cmd_path=""
    for ((i = 1; i < n; i++)); do
        w=${words[i]}
        case $w in
            -*=*) ;;
`)
	fmt.Fprintf(&b, "            %s) ((i++)) ;;\n", valueFlags)
	b.WriteString(`            -*) ;;
            *)
                case "${cmd_path:+$cmd_path }$w" in
`)
	fmt.Fprintf(&b, "                    %s) cmd_path=${cmd_path:+$cmd_path }$w ;;\n", bashCommandPathPatterns(root))
	b.WriteString(`                    *)
                        case $cmd_path in
`)
	bashWriteDefaultCommandCases(&b, root)
	b.WriteString(`                        esac
                        ;;
                esac ;;
        esac
    done

    local word=${words[n]} before_cur flag=""
    before_cur=${word%"$cur"}
    case $before_cur in
        "")
            case ${words[n-1]} in
`)
	fmt.Fprintf(&b, "                %s) flag=${words[n-1]} ;;\n", valueFlags)
	b.WriteString(`            esac ;;
        -*=) flag=${before_cur%=} ;;
        *) return ;;
    esac

    if [[ -n $flag ]]; then
        case "$cmd_path $flag" in
`)
	for _, cmd := range collectCommands(root, nil) {
		if node := findNode(root, cmd.Path); node != nil {
			bashWriteEnumCases(&b, node, commandFlagPattern(strings.Join(cmd.Path, " ")))
		}
	}
	bashWriteEnumCases(&b, root, globalFlagPattern)
	b.WriteString(`        esac
        return
    fi

    case $cmd_path in
`)
	bashWriteCommandCase(&b, "", root)
	for _, cmd := range collectCommands(root, nil) {
		if node := findNode(root, cmd.Path); node != nil {
			bashWriteCommandCase(&b, strings.Join(cmd.Path, " "), node)
		}
	}
	b.WriteString(`    esac
}

complete -F _gccli_completions gccli
`)

	return b.String()
}

func bashCommandPathPatterns(root *kong.Node) string {
	var patterns []string
	for _, cmd := range collectCommands(root, nil) {
		patterns = append(patterns, fmt.Sprintf("%q", strings.Join(cmd.Path, " ")))
	}
	return strings.Join(patterns, "|")
}

func bashWriteDefaultCommandCases(b *strings.Builder, root *kong.Node) {
	for _, cmd := range collectCommands(root, nil) {
		node := findNode(root, cmd.Path)
		if node == nil || node.DefaultCmd == nil || node.DefaultCmd.Tag.Default != "withargs" {
			continue
		}
		path := strings.Join(cmd.Path, " ")
		fmt.Fprintf(b, "                            %q) cmd_path=%q ;;\n", path, path+" "+node.DefaultCmd.Name)
	}
}

func commandFlagPattern(path string) func(flag string) string {
	return func(flag string) string { return fmt.Sprintf("%q", path+" "+flag) }
}

func globalFlagPattern(flag string) string {
	return fmt.Sprintf("*\" %s\"", flag)
}

func bashWriteEnumCases(b *strings.Builder, node *kong.Node, flagPattern func(flag string) string) {
	for _, f := range collectFlags(node) {
		if len(f.Enum) == 0 {
			continue
		}
		patterns := []string{flagPattern("--" + f.Long)}
		if f.Short != 0 {
			patterns = append(patterns, flagPattern(fmt.Sprintf("-%c", f.Short)))
		}
		fmt.Fprintf(b, "            %s) COMPREPLY=($(compgen -W '%s' -- \"$cur\")) ;;\n", strings.Join(patterns, "|"), strings.Join(f.Enum, " "))
	}
}

func bashWriteCommandCase(b *strings.Builder, path string, node *kong.Node) {
	var all []string
	for _, child := range node.Children {
		if child.Hidden || child.Type != kong.CommandNode {
			continue
		}
		all = append(all, child.Name)
	}
	for _, f := range collectFlags(node) {
		all = append(all, "--"+f.Long)
		if f.Short != 0 {
			all = append(all, fmt.Sprintf("-%c", f.Short))
		}
	}
	if len(all) == 0 {
		return
	}
	fmt.Fprintf(b, "        %q) COMPREPLY=($(compgen -W '%s' -- \"$cur\")) ;;\n", path, strings.Join(all, " "))
}

func collectValueFlags(root *kong.Node) []string {
	seen := map[string]bool{}
	add := func(node *kong.Node) {
		for _, f := range collectFlags(node) {
			if f.IsBool {
				continue
			}
			seen["--"+f.Long] = true
			if f.Short != 0 {
				seen[fmt.Sprintf("-%c", f.Short)] = true
			}
		}
	}
	add(root)
	for _, cmd := range collectCommands(root, nil) {
		if node := findNode(root, cmd.Path); node != nil {
			add(node)
		}
	}
	words := make([]string, 0, len(seen))
	for w := range seen {
		words = append(words, w)
	}
	sort.Strings(words)
	return words
}

// findNode walks the model tree to find the node at the given command path.
func findNode(root *kong.Node, path []string) *kong.Node {
	node := root
	for _, name := range path {
		found := false
		for _, child := range node.Children {
			if child.Name == name {
				node = child
				found = true
				break
			}
		}
		if !found {
			return nil
		}
	}
	return node
}
